const ml: Dict = { ...ml0, ...EXTRA.ml };

export const LANGS = [
  { code: "en", native: "English", english: "English" },
  { code: "ta", native: "தமிழ்", english: "Tamil" },
  { code: "hi", native: "हिन्दी", english: "Hindi" },
  { code: "te", native: "తెలుగు", english: "Telugu" },
  { code: "kn", native: "ಕನ್ನಡ", english: "Kannada" },
  { code: "ml", native: "മലയാളം", english: "Malayalam" },
  { code: "bn", native: "বাংলা", english: "Bengali" },
  { code: "mr", native: "मराठी", english: "Marathi" },
] as const;
export type LangCode = (typeof LANGS)[number]["code"];
const DICTS: Record<LangCode, Dict> = { en, ta, hi, te, kn, ml, bn, mr };
const STORE = "hg_lang";

const stored = (): LangCode | null => {
  try { const v = localStorage.getItem(STORE) as LangCode | null; return v && v in DICTS ? v : null; } catch { return null; }
};

type Ctx = { lang: LangCode; chosen: boolean; setLang: (l: LangCode) => void; t: (k: Key, vars?: Record<string, string | number>) => string; tx: (k: string, fallback: string) => string };
const C = createContext<Ctx>({ lang: "en", chosen: true, setLang: () => {}, t: (k) => en[k], tx: (_k, f) => f });
export const useI18n = () => useContext(C);

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setL] = useState<LangCode>(() => stored() || "en");
  const [chosen, setChosen] = useState<boolean>(() => !!stored());
  const setLang = useCallback((l: LangCode) => { setL(l); setChosen(true); try { localStorage.setItem(STORE, l); } catch { /* storage unavailable */ } }, []);
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  const t = useCallback((k: Key, vars?: Record<string, string | number>) => {
    let s = DICTS[lang][k] ?? en[k];
    if (vars) for (const [a, b] of Object.entries(vars)) s = s.replace(`{${a}}`, String(b));
    return s;
  }, [lang]);
  /** Translate by a dynamic key (e.g. a booking status); falls back to the given text when no translation exists. */
  const tx = useCallback((k: string, fallback: string) => (k in en ? (DICTS[lang][k as Key] ?? fallback) : fallback), [lang]);
  const value = useMemo(() => ({ lang, chosen, setLang, t, tx }), [lang, chosen, setLang, t, tx]);
  return <C.Provider value={value}>{children}</C.Provider>;
}


